{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C76"],
      "claim": "In humans, propranolol absolute oral bioavailability averaged 60% (range 38–85%) versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In normal subjects, encainide absolute oral bioavailability was 32 ± 7% versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In healthy adult subjects, safinamide 50 mg immediate-release tablets had about 95% absolute oral bioavailability (90% CI 90–99%) versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The strongest condition-matched numeric measurements for the supplied evidence molecules are consistently above the 20% threshold, including direct absolute bioavailability values of 32%, 60%, and 95%; therefore the prediction is high.",
  "evidence_gaps": [
    "Some records come from special populations or are estimates, but the strongest ordinary-condition absolute measurements consistently support F ≥ 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

